"use client"

import * as React from "react"

import { type Split, type ViewerAdapter, toPageGroups } from "@/lib/retab"
import { meanLikelihood } from "@/hooks/use-retab"
import {
  RetabViewerShell,
  useViewerPhase,
} from "@/components/ui/retab-viewer-shell"
import { PageGroupViewer } from "@/components/ui/page-group-viewer"
import { RetabSourcePreview } from "@/components/ui/retab-source-preview"

export interface SplitViewerProps {
  split: Split
  /** Optional adapter; when it resolves a document URL a source preview is shown. */
  adapter?: ViewerAdapter
  className?: string
}

export function SplitViewer({ split, adapter, className }: SplitViewerProps) {
  const results = split.output ?? []
  const phase = useViewerPhase({
    status: split.status,
    error: split.error,
    hasOutput: results.length > 0,
  })
  const groups = React.useMemo(() => toPageGroups(results), [results])
  const confidences = split.consensus?.likelihoods?.map((l) =>
    meanLikelihood(l.pages)
  )

  return (
    <RetabViewerShell
      title={split.file?.filename ?? "Split"}
      status={split.status}
      error={split.error}
      phase={phase}
      emptyMessage="No subdocuments were produced."
      className={className}
    >
      <PageGroupViewer
        groups={groups}
        unitLabel="subdocument"
        confidences={confidences}
      />
      {adapter ? (
        <div className="px-4 pb-4">
          <RetabSourcePreview adapter={adapter} file={split.file} />
        </div>
      ) : null}
    </RetabViewerShell>
  )
}

export { type Split }
